def control(obs):
    h=obs.get('hitch_deg',0.0)
    cam=obs.get('views',{}).get('camera',{}) or {}
    walls=cam.get('walls',[])
    left=[]; right=[]
    for b,d in walls:
        if d>0 and abs(b)>105:
            y=d*__import__('math').sin(__import__('math').radians(b))
            if y>0: left.append((d,y))
            elif y<0: right.append((d,y))
    center=0.0
    if left and right:
        # Pair the closest visible rails to estimate the corridor midpoint.
        yl=min(left,key=lambda q:q[0])[1]
        yr=max(right,key=lambda q:q[0])[1]
        center=(yl+yr)/2.0
    steer=max(-10.0,min(10.0,1.2*h-4.0*center))
    return (steer,-0.3,-23)

